            "type": "FAQ",
            "question": "Yurtimizda ortiq qayd etilmagan kasalliklar uchun ham farzandimni emlashim kerakmi?",
            "created_at": "\u003Ctime datetime=\"2022-05-03T16:38:09+02:00\" class=\"datetime\"\u003ETue, 05/03/2022 - 16:38\u003C/time\u003E\n",
